func (v RolesValue) String() string {
	return "RolesValue"
}

func (v RolesValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	var deepVal basetypes.ListValue
	switch {
	case v.Deep.IsUnknown():
		deepVal = types.ListUnknown(types.StringType)
	case v.Deep.IsNull():
		deepVal = types.ListNull(types.StringType)
	default:
		var d diag.Diagnostics
		deepVal, d = types.ListValue(types.StringType, v.Deep.Elements())
		diags.Append(d...)
	}

	if diags.HasError() {
		return types.ObjectUnknown(map[string]attr.Type{
			"deep": basetypes.ListType{
				ElemType: types.StringType,
			},
			"fast": basetypes.ListType{
				ElemType: types.StringType,
			},
			"standard": basetypes.ListType{
				ElemType: types.StringType,
			},
		}), diags
	}

	var fastVal basetypes.ListValue
	switch {
	case v.Fast.IsUnknown():
		fastVal = types.ListUnknown(types.StringType)
	case v.Fast.IsNull():
		fastVal = types.ListNull(types.StringType)
	default:
		var d diag.Diagnostics
		fastVal, d = types.ListValue(types.StringType, v.Fast.Elements())
		diags.Append(d...)
	}

	if diags.HasError() {
		return types.ObjectUnknown(map[string]attr.Type{
			"deep": basetypes.ListType{
				ElemType: types.StringType,
			},
			"fast": basetypes.ListType{
				ElemType: types.StringType,
			},
			"standard": basetypes.ListType{
				ElemType: types.StringType,
			},
		}), diags
	}

	var standardVal basetypes.ListValue
	switch {
	case v.Standard.IsUnknown():
		standardVal = types.ListUnknown(types.StringType)
	case v.Standard.IsNull():
		standardVal = types.ListNull(types.StringType)
	default:
		var d diag.Diagnostics
		standardVal, d = types.ListValue(types.StringType, v.Standard.Elements())
		diags.Append(d...)
	}

	if diags.HasError() {
		return types.ObjectUnknown(map[string]attr.Type{
			"deep": basetypes.ListType{
				ElemType: types.StringType,
			},
			"fast": basetypes.ListType{
				ElemType: types.StringType,
			},
			"standard": basetypes.ListType{
				ElemType: types.StringType,
			},
		}), diags
	}

	attributeTypes := map[string]attr.Type{
		"deep": basetypes.ListType{
			ElemType: types.StringType,
		},
		"fast": basetypes.ListType{
			ElemType: types.StringType,
		},
		"standard": basetypes.ListType{
			ElemType: types.StringType,
		},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"deep":     deepVal,
			"fast":     fastVal,
			"standard": standardVal,
		})

	return objVal, diags
}

func (v RolesValue) Equal(o attr.Value) bool {
	other, ok := o.(RolesValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Deep.Equal(other.Deep) {
		return false
	}

	if !v.Fast.Equal(other.Fast) {
		return false
	}

	if !v.Standard.Equal(other.Standard) {
		return false
	}

	return true
}

func (v RolesValue) Type(ctx context.Context) attr.Type {
	return RolesType{
		basetypes.ObjectType{
			AttrTypes: v.AttributeTypes(ctx),
		},
	}
}

